{"t":"plan","products":["users","dns","esa","alb","waf","ecs","ess","tair","rds","kms","sls","cloudmonitor"]}
{"t":"group","id":"internet","kind":"external","label":"Internet","parent":null}
{"t":"node","id":"users","product":"users","label":"Fintech customers","group":"internet","why":"Customers accessing the portal from browsers."}
{"t":"node","id":"dns","product":"dns","label":"Cloud DNS","group":null,"why":"Resolves portal domain to ESA edge."}
{"t":"edge","id":"e-users-dns","from":"users","to":"dns","kind":"resolve"}
{"t":"group","id":"edge","kind":"edge","label":"Edge","parent":null}
{"t":"node","id":"esa","product":"esa","label":"ESA","group":"edge","why":"Accelerates and caches portal assets at the edge."}
