{"t":"node","id":"waf","product":"waf","label":"WAF","group":"vpc","attachTo":"alb","why":"Blocks OWASP attacks on the financial portal."}
{"t":"edge","id":"e-esa-alb","from":"esa","to":"alb","label":"origin"}
