{"t":"node","id":"llm","product":"model-studio","label":"Model Studio","group":"sg","why":"Runs Qwen models to generate answers for customer questions."}
{"t":"node","id":"vector-db","product":"milvus","label":"Vector store","group":"vpc","zones":["a","b"],"why":"Stores fintech document embeddings for RAG retrieval."}
