{"t":"edge","id":"e-ai-gw-llm","from":"ai-gw","to":"llm","label":"LLM API"}
{"t":"edge","id":"e-ai-gw-vector-db","from":"ai-gw","to":"vector-db","label":"RAG query"}
{"t":"done","summary":"Added AI chatbot path: app → AI Gateway → Model Studio + Milvus vector store, all within Singapore."}

